-- Flyway V1: equivalent of the retired EF Core InitialCreate migration.
-- Quoted identifiers match EF Core Npgsql defaults (PascalCase table/column names).
-- IF NOT EXISTS: Lakebase public is already non-empty (helper functions), so migrate
-- baselines at 0 and still runs V1; skip CREATE when EF already applied the same objects.

CREATE TABLE IF NOT EXISTS "Members" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "MemberId" text NOT NULL,
    "FirstName" text NOT NULL,
    "LastName" text NOT NULL,
    "DateOfBirth" timestamp with time zone NOT NULL,
    "PlanType" text NOT NULL,
    "CreatedAt" timestamp with time zone NOT NULL DEFAULT (NOW()),
    "UpdatedAt" timestamp with time zone,
    CONSTRAINT "PK_Members" PRIMARY KEY ("Id")
);

CREATE TABLE IF NOT EXISTS "Providers" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "Npi" text NOT NULL,
    "Name" text NOT NULL,
    "Specialty" text NOT NULL,
    "IsActive" boolean NOT NULL,
    "PhoneNumber" text,
    "CommentsText" text,
    CONSTRAINT "PK_Providers" PRIMARY KEY ("Id")
);

CREATE TABLE IF NOT EXISTS "CareEvents" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "MemberId" integer NOT NULL,
    "EventType" text NOT NULL,
    "Description" text NOT NULL,
    "EventDate" timestamp with time zone NOT NULL,
    "CreatedAt" timestamp with time zone NOT NULL DEFAULT (NOW()),
    CONSTRAINT "PK_CareEvents" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_CareEvents_Members_MemberId" FOREIGN KEY ("MemberId") REFERENCES "Members" ("Id") ON DELETE CASCADE
);

CREATE INDEX IF NOT EXISTS "IX_CareEvents_MemberId" ON "CareEvents" ("MemberId");

CREATE UNIQUE INDEX IF NOT EXISTS "IX_Members_MemberId" ON "Members" ("MemberId");

CREATE UNIQUE INDEX IF NOT EXISTS "IX_Providers_Npi" ON "Providers" ("Npi");
